#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using DeliveryService.Yun.Streetlights;
namespace DeliveryService.Mok.Editor {
[InitializeOnLoad] public static class DistrictLampAudit {
static DistrictLampAudit(){EditorApplication.update+=Poll;}
static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists("Temp/Mok-lamp-audit"))return;File.Delete("Temp/Mok-lamp-audit");try{Run();}catch(Exception e){File.WriteAllText("Temp/Mok-lamp-audit.txt",e.ToString());}}
static void Run(){var old=SceneManager.GetActiveScene();for(int i=0;i<SceneManager.sceneCount;i++)EditorSceneManager.SaveScene(SceneManager.GetSceneAt(i),"Temp/Before-lamp-audit-"+DateTime.Now.ToString("HHmmss")+"-"+i+".unity",true);var s=SceneManager.GetSceneByPath("Assets/Scenes/JJinCity.unity");bool opened=!s.isLoaded;if(opened)s=EditorSceneManager.OpenScene("Assets/Scenes/JJinCity.unity",OpenSceneMode.Additive);SceneManager.SetActiveScene(s);var roots=s.GetRootGameObjects();var registered=new HashSet<Light>();foreach(var c in roots.SelectMany(g=>g.GetComponentsInChildren<StreetlightTimeController>(true))){var a=new SerializedObject(c).FindProperty("lamps");for(int i=0;i<a.arraySize;i++)registered.Add(a.GetArrayElementAtIndex(i).objectReferenceValue as Light);}var east=roots.First(g=>g.name=="Mok East City");var missing=east.GetComponentsInChildren<Light>(true).Where(l=>!registered.Contains(l)).ToArray();if(missing.Length>0){EditorSceneManager.SaveScene(s,"Temp/JJinCity-before-lamp-audit.unity",true);var glow=new List<GameObject>();foreach(var t in east.GetComponentsInChildren<Transform>(true).Where(t=>t.name=="East street lamp")){if(!t.GetComponentsInChildren<Light>(true).Any(l=>missing.Contains(l)))continue;glow.AddRange(t.GetComponentsInChildren<Renderer>(true).Where(r=>r.name.Contains("Lens")||r.name.Contains("Glow")).Select(r=>r.gameObject));}var obj=new GameObject("Mok Existing East Lamp Connection");var controller=obj.AddComponent<StreetlightTimeController>();controller.Configure(roots.SelectMany(g=>g.GetComponentsInChildren<DayNightCycle>()).First(),missing,glow.ToArray());EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);}SceneManager.SetActiveScene(old);if(opened)EditorSceneManager.CloseScene(s,true);File.WriteAllText("Temp/Mok-lamp-audit.txt","Additional previously unregistered lights connected: "+missing.Length);}
}}
#endif
